<script lang="ts">
	import { enhance } from '$app/forms';
	import { read_contact, validate_contact, type ContactErrors } from '#lib/contact.js';
	import type { PageProps } from './$types';
	import type { SubmitFunction } from '@sveltejs/kit';

	let { form }: PageProps = $props();

	/** Errors found in the browser; `null` once the form has been sent to the server. */
	let client_errors = $state<ContactErrors | null>(null);

	let errors: ContactErrors = $derived(client_errors ?? (form && 'errors' in form ? form.errors : {}));
	let values = $derived(form && 'values' in form ? form.values : undefined);
	let success = $derived(client_errors === null && form && 'success' in form ? form.name : null);

	const submit: SubmitFunction = ({ formData, cancel }) => {
		const found = validate_contact(read_contact(formData));
		if (Object.keys(found).length > 0) {
			client_errors = found;
			cancel();
			return;
		}
		client_errors = null;
		return async ({ update }) => {
			await update();
		};
	};
</script>

