// Starts the production build made by adapter-node.
//
// SvelteKit 3's adapter-node no longer reads the `ORIGIN` environment variable,
// and otherwise assumes `https` when deriving the request origin, which makes
// form submissions over plain http fail the CSRF check. This wrapper gives the
// handler the site's real origin (from `ORIGIN`, or plain http on the request's
// own host) through headers it sets itself, so clients cannot spoof them.
import http from 'node:http';
import process from 'node:process';

const PROTOCOL_HEADER = 'x-bookshelf-protocol';
const HOST_HEADER = 'x-bookshelf-host';

process.env.PROTOCOL_HEADER = PROTOCOL_HEADER;
process.env.HOST_HEADER = HOST_HEADER;

const origin = process.env.ORIGIN ? new URL(process.env.ORIGIN) : null;
const protocol = origin ? origin.protocol.slice(0, -1) : 'http';

const { handler } = await import('./build/handler.js');

const server = http.createServer((req, res) => {
	req.headers[PROTOCOL_HEADER] = protocol;
	req.headers[HOST_HEADER] = origin ? origin.host : (req.headers.host ?? 'localhost');
	handler(req, res, () => {
		res.statusCode = 404;
		res.end('Not found');
	});
});

const host = process.env.HOST || '0.0.0.0';
const port = Number(process.env.PORT || 3000);

server.listen(port, host, () => {
	console.log(`Listening on http://${host}:${port}`);
});

function shutdown() {
	server.close(() => process.exit(0));
	server.closeIdleConnections();
	setTimeout(() => process.exit(0), 5000).unref();
}

process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);
EOF
